proof.raw_tex:
\begin{Lemma}\label{stationary point lemma}
Let $\set{x^k}$ and $\set{d^k}$ be sequences satisfying 
\eqref{series is finite}. If $\bar x$ is an accumulation point of $\set{x^k}$ and if $0$ is an accumulation point of $\set{d^k}$, then there exists an infinite set $J\subset\N$ such that
\begin{align}\label{relation dk xk 3}
x^k\overset{J}{\rightarrow}\bar x\;\mbox{ and }\;d^k\overset{J}{\rightarrow}0.
\end{align}
\end{Lemma}

\begin{proof}
If $x^k\rightarrow\bar x$ as $k\to\infty$, the conclusion obviously holds, so suppose that $x^k\not\rightarrow \bar x$. It suffices to show that for any $\delta>0$ sufficiently small and any $N\in\N$ there is a number $k_N\ge N$ such that
\begin{align*}
\|x^{k_N}-\bar x\|<\delta\;\text{ and }\;\|d^{k_N}\|<\delta.
\end{align*}
Fix such $\delta>0$ and $N\in\N$. Since $\delta$ is sufficiently small and $x^k\not\rightarrow\bar x$, suppose that the set
\begin{align*}
A_1:=\big\{k\ge N\;\big|\;\|x^k-\bar x\|\ge\delta\big\}\;\text{ is infinite}.
\end{align*}
As $\bar x$ is an accumulation point of $\set{x^k}$ and $0$ is an accumulation point of $\set{d^k}$, we get that
\begin{align*}
A_2:&=\big\{k\ge N\;\big|\;\|x^k-\bar x\|<\delta\big\}\;\text{ is infinite},\\
A_3:&=\big\{k\ge N\;\big|\;\|x^k-\bar x\|<\delta/2\big\}\;\text{ is infinite},\\
 A_4:&=\big\{k\ge N\;\big|\;\|d^k\|<\delta\big\}\;\text{ is infinite}.
\end{align*}
It suffices to verify that $A_2\cap A_4\ne\emptyset.$ Suppose on the contrary that $A_2\cap A_4=\emptyset$, i.e.,
\begin{align*}
\|d^k\|\ge\delta\;\text{ for all }\;k\in A_2.
\end{align*}
By (\ref{series is finite}), we have the estimates
\begin{align*}
\infty> \sum_{k=1}^\infty\norm{x^{k+1}-x^k}\cdot\norm{d^k}&\ge \sum_{k\in A_2} \norm{x^{k+1}-x^k}\cdot\norm{d^k}\\
&\ge \delta\sum_{k\in A_2}\norm{x^{k+1}-x^k},
\end{align*}
which ensure the series convergence
\begin{align}\label{sum bounded 1}
\sum_{k\in A_2}\norm{x^{k+1}-x^k}<\infty.
\end{align}
Taking any number $K\in A_3$, we also have $K\in A_2.$ Since $A_1$ is infinite and  $A_1,A_2$ form a partition of the set $\set{N,N+1,\ldots}$ including $K$, there exists a number $\widehat{K}\in A_1$ with $\widehat{K}>K$ such that $K,K+1,\ldots,\widehat{K}-1\in A_2$. Then we have the estimates
\begin{align*}
\norm{x^{\widehat{K}}-x^K}\ge\norm{x^{\widehat{K}}-\bar x}-\norm{x^K-\bar x}\ge\delta-\delta/2=\delta/2.
\end{align*}
Using the triangle inequality and (\ref{sum bounded 1}) gives us
\begin{align*}
\delta/2\le\norm{x^{\widehat{K}}-x^K}\le \sum_{i=K}^{\widehat{K}-1}\norm{x^{i+1}-x^i}\le\sum_{i\ge K,\;i\in A_2}\norm{x^{i+1}-x^i}\xrightarrow[K\in A_3]{K\rightarrow\infty}0,
\end{align*}
which brings us to a contradiction that completes the proof of the lemma.
\end{proof}

\begin{Lemma}\label{lemma: ostrowski}
Let $\set{x^k}$ be a sequence satisfying the Ostrowski condition
\begin{align}\label{8.3.8}
\lim_{k\rightarrow\infty}\|x^{k+1}-x^k\|=0.
\end{align}
Then the following assertions hold:
\begin{itemize}
\item[\bf(i)] If $\set{x^k}$ is bounded, then the set of accumulation points of $\set{x^k}$ is nonempty, compact, and connected in $\R^n$.

\item[\bf(ii)] If $\set{x^k}$ has an isolated accumulation point, then this sequence converges to it.
\end{itemize}
\end{Lemma}

\begin{Theorem}\label{stationary point theorem}
Let $\set{x^k}$ be a sequence generated by a linesearch method \eqref{intro: stepsize + descent direction} such that:
\begin{itemize}
\item[\bf(a)] $\set{d^k}$ is gradient associated with $\set{x^k}$;
\item[\bf(b)] $0$ is an accumulation point of $\set{d^k};$
\item[\bf(c)] $\displaystyle{\sum_{k=1}^\infty}t_k\|d^k\|^2<\infty.$
\end{itemize}
Then every accumulation point of $\set{x^k}$ is a stationary point of $f$. Moreover, if $\set{t_k}$ is bounded from above, then the following assertions hold:
\begin{itemize}
\item[\bf(i)] If $\set{x^k}$ is bounded, then the set of accumulation points of $\set{x^k}$ is nonempty, compact, and connected.
\item[\bf(ii)] If $\set{x^k}$ has an isolated accumulation point, then this sequence converges to it.
\end{itemize}
\end{Theorem}

\begin{proof}
Let $\bar x$ be an accumulation point of $\set{x^k}$.  Note that (c) is equivalent to \eqref{series is finite} under the linesearch relationship $x^{k+1}=x^k+t_kd^k$ in (\ref{intro: stepsize + descent direction}). Applying Lemma~\ref{stationary point lemma} with taking into account (b) and (c), we can find an infinite set $J\subset\N$ such that $x^k\overset{J}{\rightarrow }\bar x$ and $d^k\overset{J}{\rightarrow}0$. Then (a) implies that $\nabla f(x^k)\overset{J}{\rightarrow}0$. Employing the continuity of $\nabla f$, we have 
\begin{align*}
\nabla f(\bar x)=\lim_{k\overset{J}{\rightarrow}\infty}\nabla f(x^k)=0,
\end{align*}
which tells us that $\bar x$ is a stationary point of $f$. Suppose now that $\set{t_k}$ is bounded from above by some $\tau>0$. Using (c), we immediately get
\begin{align*}
\sum_{k=1}^\infty\|x^{k+1}-x^k\|^2=\sum_{k=1}^\infty t_k^2\|d^k\|^2\le\tau\sum_{k=1}^\infty t_k\|d^k\|^2<\infty.
\end{align*}
This leads us to
$\norm{x^{k+1}-x^k}\rightarrow 0$ and verifies assertions (i) and (ii) by applying Lemma~\ref{lemma: ostrowski}.
\end{proof}

\begin{Proposition}\label{general convergence under KL}
Let $f:\R^n\rightarrow\R$ be a $\mathcal{C}^1$-smooth function, and let the sequence of iterations $\set{x^k}\subset\R^n$ satisfy the following conditions:
\begin{itemize}
\item[\bf(H1)] {\rm(primary descent condition)}. There exists $\sigma>0$ such that for sufficiently large $k\in\N$ we have 
\begin{align*}
 f(x^k)-f(x^{k+1})\ge\sigma\norm{\nabla f(x^k)}\cdot\norm{x^{k+1}-x^k}.
\end{align*}
\item[\bf(H2)] {\rm(complementary descent condition)}. For sufficiently large $k\in\N$, we have
\begin{align*}
 \big[f(x^{k+1})=f(x^k)\big]\Longrightarrow [x^{k+1}=x^k].
\end{align*}
\end{itemize}
If $\bar x$ is an accumulation point of $\set{x^k}$  and $f$ satisfies the KL property at $\bar x$, then $x^k\rightarrow\bar x$ as $k\to\infty$.
\end{Proposition}

Note that \cite[Theorem~3.2]{absil05} provides a detailed proof for Proposition~\ref{general convergence under KL} when $f$ satisfies the KL property at $\bar x$ with $\psi(t)=Mt^q$ for some $M>0$ and $q\in [0,1)$. The key ingredient of the proof is the existence of some $k_1\in\mathbb{N}$ such that
\begin{align}\label{kl induction}
 \norm{x^{k+1}-x^k}&\le  \dfrac{1}{\sigma M(1-q )}\sbrac{(f(x^k)-f(\bar x))^{1-q }-(f(x^{k+1})-f(\bar x))^{1-q }}\text{ for all }k\ge k_1.
\end{align}
Using this, we can deduce that
\begin{align}\label{sum series cauchy}
\sum_{k=1}^\infty \norm{x^{k+1}-x^k}<\infty,
\end{align}
and so the sequence $\set{x^k}$ is convergent.


\begin{Lemma}\label{lemma KL}
Let $\set{s_k}$ be a nonnegative sequence in $\R$, and let $\alpha,\beta$ be some positive constants. Suppose that $s_k\rightarrow 0$ as $k\to\infty$ and that this sequence satisfies the condition
\begin{align*}
s_k^\alpha\le\beta(s_k-s_{k-1})\;\text{ for all }\;k\in\N\;\text{ sufficiently large}.
\end{align*}
The following assertions hold:
\begin{enumerate}
\item[\bf (i)] If $\alpha\in(0,1]$, then $s_{k+1}\le\brac{1-\dfrac{1}{\beta}}s_k$ for all $k\in\N$ sufficiently large, i.e., $\set{s_k}$ converges linearly to $0$ with rank $1-\dfrac{1}{\beta}.$
\item[\bf (ii)] If $\alpha>1$, then there exists a number $\varrho>0$ such that 
\begin{align*}
 s_k\le\varrho k^{-\frac{1}{\alpha-1}}\;\text{ for all }\;k\in\N\;\text{ sufficiently large}.
\end{align*}
\end{enumerate}
\end{Lemma}

\begin{Theorem}\label{general rate}
Let the sequences $\set{x^k}\subset\R^n$, $\set{t_k}\subset\R_+$ and the numbers $\beta>0,\;c>0$ be such that $x^{k+1}\ne x^k$ for all $k\in\N$, and that we have
\begin{align}\label{two conditions}
f(x^k)-f(x^{k+1})\ge \dfrac{\beta}{t_k}\norm{x^{k+1}-x^k}^2\;\text{ and }\;\norm{\nabla f(x^k)}\le\dfrac{c}{t_k}\norm{x^{k+1}-x^k}
\end{align}
for sufficiently large $k\in\N$. Suppose that the sequence $\set{t_k}$ is bounded away from $0$, that $\bar x$ is an accumulation point of $\set{x^k}$, and that $f$ satisfies the KL property at $\bar x$ with $\psi(t)=Mt^{q}$ for some $M>0$ and $q\in(0,1)$. The following convergence rates are guaranteed:
\begin{itemize}\vspace*{-0.05in}
\item[\bf(i)] If $q\in(0,1/2]$, then the sequence $\set{x^k}$ converges linearly to $\bar x$.\vspace*{-0.05in}
\item[\bf(ii)]If $q\in(1/2,1)$, then there exists a positive constant $\varrho$ such that 
\begin{align*}
\norm{x^k-\bar x}\le \varrho k^{-\frac{1-q}{2q-1}}\;\text{ for sufficiently large }\;k\in\N.
\end{align*}
\end{itemize}
\end{Theorem}

\begin{proof}
The conditions imposed in (\ref{two conditions}) imply that
\begin{align*}
f(x^k)-f(x^{k+1})\ge \dfrac{\beta}{c}\norm{\nabla f(x^k)}\cdot\norm{x^{k+1}-x^k}\;\text{ for sufficiently large }\;k\in\N,
\end{align*}
which ensures that assumption (H1) in Proposition~\ref{general convergence under KL} holds with $\sigma:=\dfrac{\beta}{c}$. By
$t_k>0$ for all $k\in\N$, the first condition in (\ref{two conditions}) yields also assumption (H2) of this proposition. Let $k_1\in\N$ be such that \eqref{kl induction} is satisfied for all $k\ge k_1$, which implies in turn inequality \eqref{sum series cauchy} and thus the convergence of $\set{x^k}$ to $\ox$. Moreover, the first condition in (\ref{two conditions}) together with $x^{k+1}\ne x^k$ as $k\in\N$ implies that 
\begin{align}\label{f(xk) converges}
f(x^k)\downarrow f(\bar x):=\bar f\;\text{ and }\;f(x^k)>\bar f\;\text{ for all }\;k\in\N.
\end{align}
It follows from (\ref{sum series cauchy}) and the triangle inequality that
\begin{align*}
\norm{x^i-\bar x}\le\sum_{k=i}^\infty\norm{x^{k+1}-x^k}=:s_i<\infty\;\text{ whenever }\;i\in\N.
\end{align*}
Therefore, the convergence rate of $x^i$ to $\bar x$ can be deduced from the convergence rate of $s_i$ to $0$. Let $k_1$ be defined in (\ref{kl induction}) and pick $i\ge k_1$. Summing up (\ref{kl induction}) from $i$ to any $p>i$ gives us
\begin{align*}
\sum_{k=i}^{p}\norm{x^{k+1}-x^k}\le\dfrac{1}{\sigma M(1-q)}\big(f(x^i)-\bar f\big)^{1-q}.
\end{align*}
Letting $p\rightarrow\infty$, we get the estimate
\begin{align}\label{sikm}
s_i\le\dfrac{1}{\sigma M(1-q )}\big(f(x^i)-\bar f\big)^{1-q}\;\text{ for all }\;i\ge k_1.
\end{align}
The KL property of $f$ at $\bar x$ with $\psi(t)=Mt^{q }$ allows us to find a positive number $\eta$ and a neighborhood $U$ of $\bar x$ ensuring the condition
\begin{align}\label{KL M gradient}
\norm{\nabla f(x)}\ge M\big(f(x)-\bar f\big)^q\;\mbox{ whenever }\;x\in U,\;\bar f<f(x)<\bar f+\eta.
\end{align} 
Using (\ref{KL M gradient}), $x^k\rightarrow\bar x$, and (\ref{f(xk) converges}) gives us a natural number $k_2>k_1$ such that
\begin{align}\label{M(1-theta)}
\norm{\nabla f(x^i)}\ge M\big(f(x^i)-\bar f\big)^q\;\text{ for all }\;i\ge k_2.
\end{align}
Let $\bar{t}>0$ be a lower bound of $\set{t_k}$. Combining this with (\ref{M(1-theta)}) and the second inequality in (\ref{two conditions}), we have the estimates
\begin{align}
\big(f(x^i)-\bar f\big)^q &\le\dfrac{1}{M}\norm{\nabla f(x^i)}\le\dfrac{c}{Mt_i}\norm{x^{i+1}-x^i}\nonumber\\
&\le\dfrac{c}{M\bar{t}}\norm{x^{i+1}-x^i}\;\text{ for all }\;i\ge k_2.\label{3.220}
\end{align}
Involving further (\ref{sikm}) and (\ref{3.220}) ensures that
\begin{align*}
s_i^{\frac{q}{1-q }}&\le\brac{\dfrac{1}{\sigma M(1-q)}}^{\frac{q }{1-q}}\big(f(x^i)-\bar f\big)^q\\
&\le\brac{\dfrac{1}{\sigma M(1-q)}}^{\frac{q }{1-q}}\dfrac{c}{M\bar{t}}\norm{x^{i+1}-x^i}.
\end{align*}
Define $\alpha:=\dfrac{q }{1-q }$ and $\beta:=\brac{\dfrac{1}{\sigma M(1-q )}}^{\frac{q }{1-q }}\dfrac{c}{M\bar{t}}$, and then rewrite the latter estimate as
\begin{align*}
s_i^\alpha\le\beta(s_i-s_{i-1})\;\text{ for all }\;i\ge k_2.
\end{align*}
Applying finally Lemma~\ref{lemma KL}, we verify the convergence rates in (i), (ii), and (iii). 
\end{proof}

\begin{Proposition}\label{prop sufi holds}
In Algorithm~{\rm\ref{al gd inexact}}, $\set{d^k}$ satisfies the sufficient descent condition with constant~$1,$ i.e., 
\begin{align}\label{sufi des holds}
\dotproduct{\nabla f(x^k),d^k}\le -\norm{d^k}^2\;\text{ for all }\;k\in\N.
\end{align}
\end{Proposition}

\begin{proof}
Note that (\ref{sufi des holds}) automatically holds if $d^k=0$. Supposing that $d^k\ne 0$ and using the construction of $d^k$ in Step~\ref{Step 2}, we have the expression
\begin{align*}
-d^k={\rm Proj}\big(0,\mathbb{B}(g^k,\varepsilon_k)\big).
\end{align*}
It follows from (\ref{calculate approx grad}) that $\norm{g^k-\nabla f(x^k)}\le \varepsilon_k$, which means that $\nabla f(x^k)\in \mathbb{B}(g^k,\varepsilon_k)$. Invoking the projection description for convex sets \eqref{proj} yields
\begin{align*}
\dotproduct{0+d^k,\nabla f(x^k)+d^k}\le 0,
\end{align*}
which is in turn equivalent to
\begin{align*}
\dotproduct{\nabla f(x^k),d^k}\le-\norm{d^k}^2
\end{align*}
and thus verifies the claim in \eqref{sufi des holds}.
\end{proof}

\begin{Proposition}\label{null properties}
Let $\set{x^k},\set{g^k},\set{d^k},\set{\varepsilon_k}$, and $\set{r_k}$ be sequences generated by Algorithm~{\rm\ref{al gd inexact}}. The following assertions hold:
\begin{itemize}
\item[\bf(i)] $k\in\mathcal{N}$ if and only if either one of the equivalent conditions in \eqref{alter condi for null} holds.\vspace*{-0.05in}

\item[\bf(ii)] $\varepsilon_k\downarrow 0$ if and only if $r_k\downarrow 0$, which is equivalent to the set $\mathcal{N}$ being infinite.

\item[\bf(iii)] If $\mathcal{N}$ is finite, then we have
\begin{align*}
 \norm{g^k}>r_N+\varepsilon_N\;\text{ and }\;\norm{d^k}>r_N
\end{align*}
for all $k\ge N$, where $N:=\max\mathcal{N}+1$.

\item[\bf(iv)] If $\N\setminus\mathcal{N}$ is finite, then $\nabla f(x^K)=0$ and $\set{x^k}_{k\ge K}$ is a constant sequence, where we denote $K:=\max\{\N\setminus\mathcal{N}\}+1$. Otherwise, $\bar x$ is an accumulation point of $\set{x^k}$ if and only if it is an accumulation point of $\set{x^k}_{k\in \N\setminus\mathcal{N}}$, and therefore $x^k\rightarrow\bar x$ if and only if $x^k\overset{\N\setminus\mathcal{N}}{\longrightarrow}\bar x$.
\end{itemize}
\end{Proposition}

\begin{proof} Assertions (i) and (ii) follow directly from Definition~\ref{nul iter}. To verify (iii), observe that for any natural number $k\ge N$, the $k^{\rm th}$ iteration is not a null one and then deduce from (i) that
\begin{align*}
\varepsilon_{k+1}=\varepsilon_k=\varepsilon_N,\quad r_{k+1}=r_k=r_N,\;\mbox{ and }\;\norm{g^k}>r_k+\varepsilon_k=r_N+\varepsilon_N.
\end{align*}
Together with Step~\ref{Step 2} in Algorithm~\ref{al gd inexact}, this ensures that   
\begin{align*}
\norm{d^k}=\norm{g^k}-\varepsilon_k>r_k=r_N.
\end{align*}
which readily justifies assertion (i).

The proof of (iv) is a bit more involved. Supposing that the set $\N\setminus\mathcal{N}$ is finite, we have that $k\in \mathcal{N}$ for all $k\ge K$. This means by (i) that
\begin{align*}
x^{k+1}=x^{k},\;\varepsilon_{k+1}=\theta\varepsilon_k,\;r_{k+1}=\mu r_k,\;\text{ and }\;\norm{g^k}\le r_k+\varepsilon_k\;\text{ whenever }\;k\ge K.
\end{align*}
This tells us that $x^k=x^{K}$ for all $k\ge K$, and that $\varepsilon_k\downarrow 0,\;r_k\downarrow 0$, and $g^k\rightarrow 0$ as $k\to\infty$. Taking the limit as $k\rightarrow \infty$ in $\norm{g^k-\nabla f(x^k)}\le \varepsilon_k$ gives us $\nabla f(x^k)\rightarrow0$, which yields $\nabla f(x^{K})=0$.

Supposing otherwise that the set $\N\setminus\mathcal{N}$ is infinite, we obviously get that every accumulation point of $\set{x^k}_{k\in \N\setminus \mathcal{N}}$ is an accumulation point of $\set{x^k}$. Conversely, taking any accumulation point $\bar x$ of $\set{ x^k}$, it suffices to show that 
\begin{align*}
\mbox{for any }\;\delta>0,\;N\in\N\;\mbox{ there exists }\;k_N\in\N\setminus\mathcal{N},\;k_N\ge N\;\mbox{ with }\;\norm{x^{k_N}-\bar x}<\delta.
\end{align*}
To verify this, fixing $\delta >0$ and $N\in\N$ and remembering that $\bar x$ is an accumulation point of $\set{x^k}$, we find $K\ge N$ such that $\norm{x^K-\bar x}<\delta$. If $K\in\N\setminus\mathcal{N}$, choose $k_N:=K$. Otherwise, using that $\N\setminus\mathcal{N}$ is infinite allows us to find $\widehat{K}\in\N\setminus\mathcal{N}$ for which $K,K+1,\ldots,\widehat{K}-1\in\mathcal{N}$. This ensures that 
\begin{align*}
{x^{\widehat{K}}}={x^{\widehat{K}-1}}=\ldots=x^{K+1}=x^K,
\end{align*}
and therefore, with $k_N:=\widehat{K}$, we get that $\norm{x^{k_N}-\bar x}<\delta$. Since $\delta$ was chosen arbitrarily, this clearly shows that $\bar x$ is an accumulation point of $\set{x^k}_{k\in\N\setminus\mathcal{N}}$ and thus completes the proof. 
\end{proof}

\begin{Proposition}\label{goes to 0} Let $\set{g^k},\set{d^k},\;\set{\varepsilon_k}$, and $\set{r_k}$ be sequences generated by Algorithm~{\rm\ref{al gd inexact}}. Then for any $k\in\N$ we have the estimates
\begin{align}\label{nx1}
\norm{d^k}\le\norm{g^k}\le\norm{d^k}+\varepsilon_k+r_k.
\end{align}
Consequently, the following assertions hold:
\begin{itemize}
\item[\bf(i)] $\varepsilon_k\downarrow0$ if and only if there is an infinite set $J\subset\N$ such that $g^k\overset{J}{\rightarrow}0$.

\item[\bf(ii)] For any infinite set $J\subset\N$, we have the equivalence
\begin{align*}
g^k\overset{J}{\rightarrow}0\Longleftrightarrow d^k\overset{J}{\rightarrow}0.
\end{align*}
\end{itemize}
\end{Proposition}

\begin{proof}
Fix any $k\in\N$. If $k\in\mathcal{N}$, then we get by Proposition~\ref{null properties}(i) that $d^k=0$ and $\norm{g^k}\le \varepsilon_k+r_k$. Otherwise, Step~\ref{Step 2} in Algorithm~\ref{al gd inexact} yields $\norm{d^k}=\norm{g^k}-\varepsilon_k\le \norm{g^k}$. In both cases, (\ref{nx1}) holds. 

To deduce (i) from (\ref{nx1}), suppose that $\varepsilon_k\downarrow 0$ as $k\to\infty$. By Proposition~\ref{null properties}(ii) we have that $r_k\downarrow 0$ and the set $\mathcal{N}$ is infinite. Then for any $\delta>0$ and $N\in\N$ there is $k\ge N$ with $k\in\mathcal{N}$ such that
\begin{align*}
\norm{g^{k}}\le r_k+\varepsilon_k<\delta,
\end{align*}
where the first inequality follows from (\ref{alter condi for null}). Thus we can construct an infinite set $J\subset\N$ such that $g^k\overset{J}{\longrightarrow}0$. If conversely the sequence $\set{\varepsilon_k}$ does not converge to $0$, then the set $\mathcal{N}$ is finite by Proposition~\ref{null properties}(ii). Using Proposition~\ref{null properties}(iii) confirms that $\set{g^k}$ is bounded away from $0$, which tells us that such an index set $J$ does not exist.

To verify now assertion (ii), observe that assuming $g^k\overset{J}{\rightarrow}0$, implies by the first inequality in (\ref{nx1}) that $d^k\overset{J}{\rightarrow}0$. Conversely, suppose that $d^k\overset{J}{\rightarrow}0$ and deduce from Proposition~\ref{null properties}(i) that the set $\mathcal{N}$ is infinite. Then it follows from Proposition~\ref{null properties}(ii) that  $\varepsilon_k\downarrow0$ and $r_k\downarrow0$ as $k\to\infty$. Using the second inequality in (\ref{nx1}), we arrive at $g^k\overset{J}{\rightarrow}0$ and thus complete the proof of the proposition.
\end{proof}

\begin{Corollary}\label{overall} The sequence $\set{d^k}$ in Algorithms~{\rm\ref{al gd inexact}} is gradient associated with $\set{x^k}$.
\end{Corollary}

\begin{proof} It follows from Proposition \ref{goes to 0} that the convergence $d^k\overset{J}{\rightarrow}0$ yields $g^k\overset{J}{\rightarrow}0$ and $\varepsilon_k\downarrow0.$ Thus we get  $\nabla f(x^k)\overset{J}{\rightarrow}0$ by taking into account $\norm{g^k-\nabla f(x^k)}\le \varepsilon_k$ from \eqref{calculate approx grad}. This shows therefore that the sequence $\set{d^k}$ is gradient associated with $\set{x^k}$.
\end{proof}

\begin{Proposition}\label{descent} If $d^k\ne 0$, then there exists a positive number $\bar t$ such that 
\begin{align*}
f(x^k+td^k)\le f(x^k)-\beta t\big\|d^k\big\|^2\;\text{ for all }\;t\in [0,\bar t],
\end{align*}
which ensures the existence of the stepsize sequence $\{t_k\}$ in \eqref{defi: tk}. 
\end{Proposition}

\begin{proof} Suppose that $d^k\ne 0$ and get by Proposition~\ref{prop sufi holds} that $\dotproduct{\nabla f(x^k),d^k}\le-\norm{d^k}^2$. By the differentiability of $f$ at $x^k$, for each $t>0$ sufficiently small we have
\begin{align*}
f(x^k+td^k)-f(x^k)&=t\dotproduct{\nabla f(x^k),d^k}+o(t)\le-t\norm{d^k}^2+o(t)\\
&=-\beta t\norm{d^k}^2+t\brac{
(\beta-1)\norm{d^k}^2+ \dfrac{o(t)}{t}}.
\end{align*}
Since $o(t)/t\rightarrow0$ as $t\dn 0$ and since $(\beta-1)\norm{d^k}^2<0$, there exists $\bar t>0$ such that 
\begin{align*}
f(x^k+td^k)\le f(x^k)-\beta t\norm{d^k}^2\;\text{ for all }\;t\in(0,\bar t].
\end{align*}
Therefore, all the numbers $t_k$ introduced in (\ref{defi: tk}) are well-defined.
\end{proof}

\begin{Theorem}\label{convergence 1}
Let $\set{x^k}$ be the sequence of iterations generated by Algorithm~{\rm\ref{al gd inexact}} with the stepsize sequences $t_k$ from \eqref{defi: tk} of the backtracking line search. Assume that $\inf f(x^k)>-\infty$ and that $\rho_k\rightarrow0$ as $k\rightarrow\infty$. Then the following assertions hold:
\begin{itemize}
\item[\bf(i)] $\varepsilon_k\downarrow0$ and $r_k\downarrow 0$ as $k\to\infty$.

\item[\bf(ii)] Every accumulation point of $\set{x^k}$ is a stationary point of $f$.

\item[\bf(iii)] If the sequence $\set{x^k}$ is bounded, then the set of accumulation points of $\set{x^k}$ is nonempty, compact, and connected.

\item[\bf(iv)] If $\set{x^k}$ has an isolated accumulation point, then the entire sequence $\set{x^k}$ converges to this point.
\end{itemize}
\end{Theorem}

\begin{proof} From the choice of $\set{t_k}$ and Step~4 in Algorithm~\ref{al gd inexact}, for every $k\in\N$ we have
\begin{align}\label{tk dk}
\beta t_k\norm{d^k}^2\le f(x^k)-f(x^{k+1}).
\end{align}
Since $\inf f(x^k)>-\infty$, summing up  on both sides of (\ref{tk dk}) over $k=1,2,\ldots$ and using the relation $x^{k+1}=x^k+t_kd^k$, we get that
\begin{align}\label{taking sum 1}
\sum_{k=1}^\infty t_k\norm{d^k}^2<\infty\quad\text{ and }\quad \sum_{k=1}^\infty\norm{x^{k+1}-x^k}\cdot\norm{d^k}<\infty.
\end{align}

To verify assertion (i), recall by Proposition~\ref{null properties}(ii) that the convergence $\varepsilon_k\downarrow0$ is equivalent to $r_k\downarrow 0$ and to the fact that the set of null iterations $\mathcal{N}$ is infinite. Assume on the contrary that $\mathcal{N}$ is finite. By Proposition~\ref{null properties}(iii) with $N=\max\mathcal{N}+1$, we have
\begin{align}\label{dk bounded}
\norm{g^k}>r_N+\varepsilon_N\;\text{ and }\;\norm{d^k}>  r_N\;\text{ for all }\;k\ge N.
\end{align}
Then (\ref{taking sum 1}) gives us $\sum_{k=1}^\infty t_k<\infty$ and thus $t_k\downarrow0$ as $k\to\infty$. Choosing a larger number $N$ if necessary, we get that $t_k<1$ for all $k\ge N$. For such $k$, it follows from the exit condition of the algorithm that
\begin{align}\label{exit inexact}
-\gamma^{-1}\beta t_k\norm{d^k}^2< f(x^{k}+\gamma^{-1}t_kd^k)-f(x^k).
\end{align}
By the classical mean value theorem, there exists some $\tilde{x}^k\in[x^k,x^k+\gamma^{-1}t_kd^k]$ such that 
\begin{align*}
f(x^{k}+\gamma^{-1}t_kd^k)-f(x^k)= \gamma^{-1}t_k\dotproduct{d^k,\nabla f(\tilde{x}^k)}.
\end{align*}
Combining the latter with (\ref{exit inexact}) tells us that
\begin{align}\label{contra 1}
\dotproduct{-d^k,\nabla f(\tilde{x}^k)}\le\beta \norm{d^k}^2\;\text{ for all }\;k\ge N.
\end{align}
Using (\ref{taking sum 1}) and (\ref{dk bounded}), we have $\sum_{k=1}^\infty\norm{x^{k+1}-x^k}<\infty$, and thus $\set{x^k}$ converges to some $\bar x\in\R^n$. The continuity of $\nabla f$ ensures that $\nabla f(x^k)\rightarrow\nabla f(\bar x)$. Then employing $\norm{g^k-\nabla f(x^k)}\le \rho_k\rightarrow0$ yields $g^k\rightarrow\nabla f(\bar x)$ as $k\rightarrow\infty$.
It follows from Step~\ref{Step 2} that
\begin{align*}
-d^k&=\dfrac{\norm{g^k}-\varepsilon_k}{\norm{g^k}}g^k=\dfrac{\norm{g^k}-\varepsilon_N}{\norm{g^k}}g^k\;\text{ for all \;}k\ge N.
\end{align*}
Letting $k\rightarrow\infty$ leads us to the equalities
\begin{align}\label{1.8 1}
-d^k\rightarrow\bar g:=\dfrac{\norm{\nabla f(\bar x)}- \varepsilon_N }{\norm{\nabla f(\bar x)}}\nabla f(\bar x)={\rm Proj}\big(0,\mathbb{B}(\nabla f(\bar x),\varepsilon_N)\big).
\end{align}
Using $t_k\downarrow0$, we get that $\tilde{x}^k\rightarrow\bar x$, and thus $\nabla f(\tilde{x}^k)\rightarrow\nabla f(\bar x)$ as $k\to\infty$. Combining the latter with (\ref{contra 1}), (\ref{1.8 1}), and the projection characterization in \eqref{proj} verifies the estimates
\begin{align}
\norm{\bar g}^2\le\dotproduct{\bar g,\nabla f(\bar x)}\le\beta \norm{\bar g}^2.
\end{align}
This tells us that $\bar g=0$, which contradicts the condition $\norm{\bar g}\ge r_N$ by (\ref{dk bounded}). Therefore, we arrive at $\varepsilon_k\downarrow 0$ and $r_k\downarrow 0$ as $k\to\infty$, which completes the proof of assertion (i).

To justify assertions (ii)--(iv), recall from Corollary~\ref{overall} that $\set{d^k}$ is \textit{gradient associated} with $\set{x^k}$. Since $\varepsilon_k\downarrow 0$, we deduce from Proposition~\ref{goes to 0} that 
$0$ is an accumulation point of $\set{d^k}$. Combining these facts with (\ref{taking sum 1}) and $t_k\le 1$ whenever $k\in\N$ ensures that all the assumptions of Theorem~\ref{stationary point theorem} are satisfied. Therefore, we verify assertions (ii)--(iv) and finish the proof of the theorem.
\end{proof}

\begin{Lemma}\label{gradien 3 dk}
Let $\set{x^k}$ be the sequence generated by Algorithm~{\rm\ref{al gd inexact}} with $\theta<\mu$. Assume that  $\varepsilon_k\downarrow 0$ and $r_k\downarrow0$ as $k\to\infty$. Then there exists some $N\in\N$ such that
\begin{align}\label{equation grad 3k}
\norm{\nabla f(x^k)}\le 3\norm{d^k}\;\text{ for all }\;k\notin\mathcal{N},\;k\ge N,
\end{align}
where the set $\mathcal{N}$ is taken from Definition~{\rm\ref{nul iter}}.
\end{Lemma}

\begin{proof} It follows directly from the assumptions of the lemma that there exists a natural number $N$ such that $\varepsilon_k\le r_k$ for all $k\ge N$. By Step~\ref{Step 2} of the algorithm, for any $k\ge N$ with $k\notin\mathcal{N}$ we have $\norm{g^k}>r_k+\varepsilon_k$ with the direction $d^k$ calculated in (\ref{choose dk}). Thus for such $k$ we get the estimates
\begin{align}\label{66}
\norm{d^k}=\norm{g^k}-\varepsilon_k>r_k+\varepsilon_k-\varepsilon_k= r_k\ge\varepsilon_k.
\end{align}
It follows from (\ref{calculate approx grad}) in Step~\ref{Step 1} and from (\ref{66}) that
\begin{align*}
\norm{\nabla f(x^k)}\le \norm{g^k}+\varepsilon_k=\norm{d^k}+2\varepsilon_k\le 3\norm{d^k},
\end{align*}
which verifies the conclusion of the lemma.
\end{proof}

\begin{Theorem}\label{convergence under KL}
Let $\set{x^k}$ be the iterative sequence generated by Algorithm~{\rm\ref{al gd inexact}} with the backtracking linesearch such that $\theta<\mu$. Assume that $\rho_k\rightarrow0$ as $k\rightarrow\infty$, $\set{x^k}$ has an accumulation point $\bar x$, and $f$ satisfies the KL property at $\bar x$. Then $\bar x$ is a stationary point of $f$, and we have $x^k\rightarrow\bar x$ as $k\to\infty$.
\end{Theorem}

\begin{proof}
Since $\bar x$ is an accumulation point of $\set{x^k}$, we can find some infinite set $J\subset\N$ such that $x^k\overset{J}{\rightarrow}\bar x$. It follows from the choice of $\set{t_k}$ in \eqref{defi: tk} that $\set{f(x^k)}$ is nonincreasing, which implies that 
\begin{align*}
\inf_{k\in \N} f(x^k)= \inf_{k\in J} f(x^k)=f(\bar x)>-\infty.
\end{align*}
Therefore, the results of Theorem~\ref{convergence 1} tell us that $\bar x$ is a stationary point of $f$ and that $\varepsilon_k\dn 0$, $r_k\downarrow 0$ as $k\to\infty$. We employ Proposition~\ref{general convergence under KL} to verify that $x^k\rightarrow\bar x$ along the entire sequence of iterations. Indeed, the imposed assumptions and the convergence $\varepsilon_k\dn 0$, $r_k\downarrow 0$ as $k\to\infty$ guarantee that all the requirements  of Lemma~\ref{gradien 3 dk} are satisfied. Pick $N\in\N$ such that (\ref{equation grad 3k}) holds. The choice of $\set{t_k}$ in (\ref{defi: tk}) ensures the lower estimate
\begin{align}\label{5.133}
f(x^{k})-f(x^{k+1})&\ge\beta t_k\big\|d^k\big\|^2\;\text{ for all }\;k\in\N.
\end{align}
Combining this with (\ref{equation grad 3k}) and the relation $x^{k+1}=x^k+t_kd^k$ yields
\begin{align}\label{5.13}
f(x^{k})-f(x^{k+1})\ge\dfrac{\beta}{3}\norm{\nabla f(x^k)}\cdot\norm{x^{k+1}-x^k}\;\text{ for all }\;k\notin\mathcal{N},\;k\ge N.
\end{align}
Observe that when $k\in\mathcal{N}$, both sides of
(\ref{5.13}) reduce to zero, and so (\ref{5.13}) is satisfied. Therefore, assumption (H1) in Proposition~\ref{general convergence under KL} holds. Moreover, for $k\ge N$ the conditions $f(x^{k+1})=f(x^k)$ and (\ref{5.133}) imply that $d^k=0$, and hence $x^{k+1}=x^k$. Thus assumption (H2) in  Proposition~\ref{general convergence under KL} is satisfied as well. Applying the latter proposition, we arrive at $x^k\rightarrow\bar x$ as $k\to\infty$ and complete the proof.
\end{proof}

\begin{Proposition}\label{bounded away}
Let $\set{x^k}$ be a sequence generated by Algorithm~{\rm\ref{al gd inexact}} with the backtracking stepsize. Suppose that $\rho_k\rightarrow0$ as $k\rightarrow\infty$ and that there exists an infinite set $J\subset\N$ such that $\set{x^k}_{k\in J}$ converges to some $\bar x$. Assume further that $\nabla f$ is locally Lipschitzian around $\bar x$. Then the stepsize sequence $\set{t_k}_{k\in J}$ is bounded away from zero.
\end{Proposition}

\begin{proof}
 Assume on the contrary that $\set{t_k}_{k\in J}$ is not bounded away from zero. Then we find an infinite set $\bar J\subset J$ such that $t_k\overset{\bar J}{\longrightarrow}0$. Let $\tau\in(0,1)$ be an artificial stepsize of null iterations. Since $t_k\overset{\bar J}{\longrightarrow}0$, there exists a number $N\in\N$ such that 
 \begin{align}\label{tk < tau}
t_k<\tau<1\;\text{ for all }\;k\ge N,\;k\in\bar J.
 \end{align}
 This means that $k\notin\mathcal{N}$ whenever $k\ge N,\;k\in\bar J$. By Proposition~\ref{null properties}(i), we have $d^k\ne 0$ for all $k\ge N,\;k\in\bar J$. Then condition (\ref{choose dk}) in Step~\ref{Step 2} leads us to
\begin{align}\label{norm dk < norm gk}
\norm{d^k}=\norm{g^k}-\varepsilon_k\le\norm{g^k}\;\mbox{ for all }\;k\ge N,\;k\in\bar J.
\end{align}
Since $x^k\overset{\bar J}{\rightarrow}\bar x$, the continuity of $\nabla f$ and the estimate $\norm{\nabla f(x^k)-g^k}\le \rho_k\rightarrow0$ yield that $g^k\overset{\bar J}{\rightarrow}\nabla f(\bar x)$. Using (\ref{norm dk < norm gk}), we get that the sequence $\set{d^k}_{k\in\bar J}$ is bounded, and thus 
\begin{align}\label{bound of norm dk}
x^k+\gamma^{-1} t_kd^k\rightarrow\bar x\;\mbox{ as }\;k\overset{\bar J}{\rightarrow}\infty.
\end{align}
Since $\nabla f$ is locally Lipschitzian around $\bar x$, there exists a positive number $\delta$ such that $\nabla f$ is Lipschitz continuous on $\mathbb{B}(\bar x,\delta)$ with some modulus $L>0$. By (\ref{bound of norm dk}) and $x^k\overset{\bar J}{\rightarrow}\bar x$, we find $N_1\ge N$ with $x^k,x^k+\gamma^{-1}t_kd^k\in\mathbb{B}(\bar x,\delta)$ for all $k\ge N_1,\;k\in\bar J$. The Lipschitz continuity of $\nabla f$ on $\mathbb{B}(\bar x,\delta)$ with modulus $L$ yields by \cite[Proposition~A.24]{bertsekasbook} the $L$-descent condition, i.e.,
\begin{align}\label{lipschitz}
f(x)-f(y)\le\dotproduct{\nabla f(y),x-y}+\dfrac{L}{2}\norm{x-y}^2\;\text{ for all }\;x,y\in \mathbb{B}(\bar x,\delta).
\end{align}
Fixing $k\in\bar J,\;k\ge N_1$, we deduce from the above that $d^k\ne 0$, and $t_k<1$. The exit condition for the backtracking line search implies that
\begin{align}\label{exit 2}
-\gamma^{-1}\beta t_k\norm{d^k}^2<f(x^{k}+\gamma^{-1}t_kd^k)-f(x^k).
\end{align}
Applying (\ref{lipschitz}) for $x=x^{k}+\gamma^{-1}t_kd^k$ and $y=x^k$ we have that
\begin{align*}
f(x^{k}+\gamma^{-1}t_kd^k)-f(x^k)\le\gamma^{-1}t_k\dotproduct{\nabla f(x^k),d^k}+\dfrac{L\gamma^{-2}t_k^2}{2}\norm{d^k}^2.
\end{align*}
Combining this with (\ref{exit 2}) leads us to 
\begin{align*}
-\gamma^{-1}\beta t_k\norm{d^k}^2<\gamma^{-1}t_k\dotproduct{\nabla f(x^k),d^k}+\dfrac{L\gamma^{-2}t_k^2}{2}\norm{d^k}^2,
\end{align*}
or equivalently to the inequality 
\begin{align}\label{0< gamma-1}
0<\gamma^{-1}\beta t_k\norm{d^k}^2+\gamma^{-1}t_k\dotproduct{\nabla f(x^k),d^k}+\dfrac{L\gamma^{-2}t_k^2}{2}\norm{d^k}^2.
\end{align}
Proposition~\ref{prop sufi holds} and $d^k\ne 0$ tell us that $0<\norm{d^k}^2\le\dotproduct{\nabla f(x^k),-d^k}$. Then we deduce from (\ref{0< gamma-1}) the fulfillment of the estimate
\begin{align*}
0<\gamma^{-1}\beta t_k\dotproduct{\nabla f(x^k),-d^k}+\gamma^{-1}t_k\dotproduct{\nabla f(x^k),d^k}+\dfrac{L\gamma^{-2}t_k^2}{2}\dotproduct{\nabla f(x^k),-d^k}.
\end{align*}
Dividing both sides above by $\gamma^{-1}t_k\dotproduct{\nabla f(x^k),-d^k}>0$, we get $0<\beta-1+\dfrac{L\gamma^{-1}t_k}{2}$.
Letting $k\overset{\bar J}{\longrightarrow}\infty$ yields $\beta\ge 1$, which contradicts the choice of $\beta\in(0,1)$. Thus we verify that the sequence $\set{t_k}_{k\in J}$ is bounded away from zero, which completes the proof of the proposition.
\end{proof}

