\begin{Definition}\rm\label{defi: approximate gradient}
Let $\set{x^k}$ be a sequence in $\R^n$. The direction sequence $\set{d^k}$ is called \textit{gradient associated} with $\set{x^k}$ if we have the implication
\begin{align}\label{condition for stationarity}
\text{ whenever }\;d^k\overset{J}{\rightarrow}0\;\text{ for some infinite set }\;J\subset\N,\;\text{ it holds that }\;\nabla f(x^k)\overset{J}{\rightarrow}0.
\end{align}
\end{Definition}

\begin{Definition}\rm \label{KL ine}\rm
Let $f:\R^n\rightarrow\R$ be a differentiable function. We say that $f$ satisfies the \textit{KL property} at $\bar{x}\in\R^n$ if there exist a number $\eta>0$, a neighborhood $U$ of $\bar{x}$, and a nondecreasing function $\psi:(0,\eta)\rightarrow(0,\infty)$ such that the function $1/\psi$ is integrable over $(0,\eta)$ and we have
\begin{align}\label{kl absil}
 \norm{\nabla f(x)}\ge\psi\big(f(x)-f(\bar{x})\big)
\end{align}
for all $x\in U$ with $f(\bar x)<f(x)<f(\bar x)+\eta$.
\end{Definition}

\begin{align}\label{series is finite}
\sum_{k=1}^\infty\norm{x^{k+1}-x^k}\cdot\norm{d^k}<\infty.
\end{align}

Prior to introducing our IRG methods, let us briefly describe the GS scheme based on the $\ve$-generalized gradient in the smooth case \eqref{egg-smooth}. Recall that the 
{\em projection} ${\rm Proj}(x,\O)$ of $x\in\R^n$ onto a closed and convex set $\O\subset\R^n$ is a singleton that is characterized by 
\begin{align}\label{proj}
u={\rm Proj}(x,\O)\;\text{ if and only if $u\in\O$ and  }\;\dotproduct{y-u,x-u}\le 0\;\text{ for all }\;y\in\O.
\end{align}

\begin{Algorithm}[\bf general framework for IRG methods]\rm \label{al gd inexact}
\quad
\setcounter{Step}{-1}
\begin{Step}[initialization]\rm Select an initial point $x^1\in \R^n$, initial radii $\varepsilon_1,r_1> 0$, radius reduction factors $\mu,\theta\in(0,1)$, a sequence of manually controlled errors $\set{\rho_k}\subset \R_+.$
\end{Step}
\begin{Step}[inexact gradient and stopping criterion]\rm \label{Step 1}
Choose $g^k$ such that 
\begin{align}\label{calculate approx grad}
\norm{g^k-\nabla f(x^k)}\le \min\set{\varepsilon_k,\rho_k}.
\end{align}
\end{Step}
\begin{Step}[radius update]\rm \label{Step 2}
If $\norm{g^k}\le r_{k}+\varepsilon_k$, then set $r_{k+1}:=\mu r_k,\;\varepsilon_{k+1}:=\theta\varepsilon_k$, $d^k:=0$, and go to~Step~3. Otherwise, set $r_{k+1}:=r_k$, $\varepsilon_{k+1}:=\varepsilon_k$, and 
\begin{align}\label{choose dk}
d^k:=-\dfrac{\norm{g^k}-\varepsilon_k}{\norm{g^k}}g^k.
\end{align}
\end{Step}
\begin{Step}[stepsize]\rm\label{Step: 3}
Choose $t_k>0$ by a specific rule.
\end{Step}
\begin{Step}[iteration update]\rm\label{step 4}
Set $x^{k+1}:=x^{k}+t_kd^k$.
\end{Step}
\begin{Step}\rm
Increase $k$ by $1$ and go back to Step $1.$
\end{Step}
\end{Algorithm}

\item[\bf(iii)] For each $k\in\N$, we have from Step~\ref{Step 2} and Step~\ref{Step: 3} the equivalences
\begin{align}\label{alter condi for null}
x^{k+1}=x^k\Longleftrightarrow d^k=0\Longleftrightarrow r_{k+1}=\mu r_k\Longleftrightarrow\varepsilon_{k+1}=\theta\varepsilon_k\Longleftrightarrow\norm{g^k}\le r_k+\varepsilon_k.
\end{align}

\begin{Definition}\rm\label{nul iter}
The $k^{\rm th}$ iteration of Algorithm~{\rm\ref{al gd inexact}} is called a {\em null iteration} if $x^{k+1}=x^k$. The set of all null iterations is denoted by
$$
\mathcal{N}:=\big\{k\in\N\;\big|\;x^{k+1}=x^k\big\}.
$$
\end{Definition}

In this section, we develop novel IRG methods with the following selections of stepsize rules: {\em backtracking stepsize}, {\em constant stepsize}, and {\em diminishing stepsize}. Address first an IRG method with the {\em backtracking line search}. Choose a line search scalar $\beta\in(0,1)$, a reduction factor $\gamma\in(0,1)$, and an artificial stepsize of null iterations $\tau\in(0,1)$. Consider the {\em Master Algorithm}~\ref{al gd inexact} with the stepsize sequence $\set{t_k}$ in Step~3 calculated as follows. If $d^k=0$, then put $t_k:=\tau$. Otherwise, we set
\begin{align}\label{defi: tk}
t_k:=\max\big\{t\;\big|\;f(x^k+td^k)\le f(x^k)-\beta t\big\|d^k\big\|^2,\;t=1,\;\gamma,\;\gamma^2,\ldots\big\}.
\end{align}

The last two theorems establish efficient conditions ensuring the {\em convergence rates} in Algorithm~\ref{al gd inexact} under different stepsize selections. Having the sequence of iterations $\set{x^k}$ generated by this algorithm, we obtain first from Proposition~\ref{null properties}(iii) that if $\N\setminus\mathcal{N}$ is finite, then $\set{x^k}$ stops after a finite number of iterations. Thus we consider the case where the set $\N\setminus\mathcal{N}$ is infinite and can be numerated as $\set{j_1,j_2,\ldots}$. Construct the sequence $\set{z^k}$ by
\begin{align}\label{z_k}
 z^k:=x^{j_k}\;\text{ for all }\;k\in\N.
\end{align}

