$\norm{x^{k+1}-x^k}\rightarrow 0$ and verifies assertions (i) and (ii) by applying Lemma~\ref{lemma: ostrowski}.

\begin{Proposition}\label{general convergence under KL}
Let $f:\R^n\rightarrow\R$ be a $\mathcal{C}^1$-smooth function, and let the sequence of iterations $\set{x^k}\subset\R^n$ satisfy the following conditions:
\begin{itemize}
\item[\bf(H1)] {\rm(primary descent condition)}. There exists $\sigma>0$ such that for sufficiently large $k\in\N$ we have 
\begin{align*}
 f(x^k)-f(x^{k+1})\ge\sigma\norm{\nabla f(x^k)}\cdot\norm{x^{k+1}-x^k}.
\end{align*}
\item[\bf(H2)] {\rm(complementary descent condition)}. For sufficiently large $k\in\N$, we have
\begin{align*}
 \big[f(x^{k+1})=f(x^k)\big]\Longrightarrow [x^{k+1}=x^k].
\end{align*}
\end{itemize}
If $\bar x$ is an accumulation point of $\set{x^k}$  and $f$ satisfies the KL property at $\bar x$, then $x^k\rightarrow\bar x$ as $k\to\infty$.
\end{Proposition}

Note that \cite[Theorem~3.2]{absil05} provides a detailed proof for Proposition~\ref{general convergence under KL} when $f$ satisfies the KL property at $\bar x$ with $\psi(t)=Mt^q$ for some $M>0$ and $q\in [0,1)$. The key ingredient of the proof is the existence of some $k_1\in\mathbb{N}$ such that
\begin{align}\label{kl induction}
 \norm{x^{k+1}-x^k}&\le  \dfrac{1}{\sigma M(1-q )}\sbrac{(f(x^k)-f(\bar x))^{1-q }-(f(x^{k+1})-f(\bar x))^{1-q }}\text{ for all }k\ge k_1.
\end{align}
Using this, we can deduce that
\begin{align}\label{sum series cauchy}
\sum_{k=1}^\infty \norm{x^{k+1}-x^k}<\infty,
\end{align}
and so the sequence $\set{x^k}$ is convergent.

Note that \cite[Theorem~3.2]{absil05} provides a detailed proof for Proposition~\ref{general convergence under KL} when $f$ satisfies the KL property at $\bar x$ with $\psi(t)=Mt^q$ for some $M>0$ and $q\in [0,1)$. The key ingredient of the proof is the existence of some $k_1\in\mathbb{N}$ such that
\begin{align}\label{kl induction}
 \norm{x^{k+1}-x^k}&\le  \dfrac{1}{\sigma M(1-q )}\sbrac{(f(x^k)-f(\bar x))^{1-q }-(f(x^{k+1})-f(\bar x))^{1-q }}\text{ for all }k\ge k_1.
\end{align}

Using this, we can deduce that
\begin{align}\label{sum series cauchy}
\sum_{k=1}^\infty \norm{x^{k+1}-x^k}<\infty,
\end{align}
and so the sequence $\set{x^k}$ is convergent.

\begin{Lemma}\label{lemma KL}
Let $\set{s_k}$ be a nonnegative sequence in $\R$, and let $\alpha,\beta$ be some positive constants. Suppose that $s_k\rightarrow 0$ as $k\to\infty$ and that this sequence satisfies the condition
\begin{align*}
s_k^\alpha\le\beta(s_k-s_{k-1})\;\text{ for all }\;k\in\N\;\text{ sufficiently large}.
\end{align*}
The following assertions hold:
\begin{enumerate}
\item[\bf (i)] If $\alpha\in(0,1]$, then $s_{k+1}\le\brac{1-\dfrac{1}{\beta}}s_k$ for all $k\in\N$ sufficiently large, i.e., $\set{s_k}$ converges linearly to $0$ with rank $1-\dfrac{1}{\beta}.$
\item[\bf (ii)] If $\alpha>1$, then there exists a number $\varrho>0$ such that 
\begin{align*}
 s_k\le\varrho k^{-\frac{1}{\alpha-1}}\;\text{ for all }\;k\in\N\;\text{ sufficiently large}.
\end{align*}
\end{enumerate}
\end{Lemma}

\begin{Theorem}\label{general rate}
Let the sequences $\set{x^k}\subset\R^n$, $\set{t_k}\subset\R_+$ and the numbers $\beta>0,\;c>0$ be such that $x^{k+1}\ne x^k$ for all $k\in\N$, and that we have
\begin{align}\label{two conditions}
f(x^k)-f(x^{k+1})\ge \dfrac{\beta}{t_k}\norm{x^{k+1}-x^k}^2\;\text{ and }\;\norm{\nabla f(x^k)}\le\dfrac{c}{t_k}\norm{x^{k+1}-x^k}
\end{align}
for sufficiently large $k\in\N$. Suppose that the sequence $\set{t_k}$ is bounded away from $0$, that $\bar x$ is an accumulation point of $\set{x^k}$, and that $f$ satisfies the KL property at $\bar x$ with $\psi(t)=Mt^{q}$ for some $M>0$ and $q\in(0,1)$. The following convergence rates are guaranteed:
\begin{itemize}\vspace*{-0.05in}
\item[\bf(i)] If $q\in(0,1/2]$, then the sequence $\set{x^k}$ converges linearly to $\bar x$.\vspace*{-0.05in}
\item[\bf(ii)]If $q\in(1/2,1)$, then there exists a positive constant $\varrho$ such that 
\begin{align*}
\norm{x^k-\bar x}\le \varrho k^{-\frac{1-q}{2q-1}}\;\text{ for sufficiently large }\;k\in\N.
\end{align*}
\end{itemize}
\end{Theorem}

\begin{proof}
The conditions imposed in (\ref{two conditions}) imply that
\begin{align*}
f(x^k)-f(x^{k+1})\ge \dfrac{\beta}{c}\norm{\nabla f(x^k)}\cdot\norm{x^{k+1}-x^k}\;\text{ for sufficiently large }\;k\in\N,
\end{align*}
which ensures that assumption (H1) in Proposition~\ref{general convergence under KL} holds with $\sigma:=\dfrac{\beta}{c}$. By
